ate.combat_effect_timing_policy_versions t) v union all select 'app_private.runtime_item_source_definitions' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.runtime_item_source_definitions t where not(content_version=6 and item_id in(select d#>>'{source,id}' from polish_targets))) v union all select 'app_private.character_item_inventory' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.character_item_inventory t) v union all select 'app_private.character_item_stacks' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.character_item_stacks t) v union all select 'app_private.character_item_grants' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.character_item_grants t) v;
do $release$ declare x jsonb; owner_id uuid; ember jsonb; result jsonb; begin
 if clock_timestamp()<timestamptz '2026-11-06T01:35:08.425950Z' or exists(select 1 from pg_stat_activity where pid<>pg_backend_pid() and backend_type='client backend' and xact_start<timestamptz '2026-11-06T01:02:38.425949Z') then raise exception 'POLISH_DRAIN_INCOMPLETE';end if;
 if (select count(*) from polish_targets)<>20 then raise exception 'POLISH_SCOPE';end if;
 if exists(select 1 from app_private.combat_content_drafts where content_key in(select d#>>'{source,id}' from polish_targets)) then raise exception 'POLISH_OWNER_DRAFT_PRESENT';end if;
 if exists(select 1 from app_private.combat_content_versions where content_key in(select d#>>'{source,id}' from polish_targets) and content_version>=6) or exists(select 1 from app_private.runtime_item_source_definitions where item_id in(select d#>>'{source,id}' from polish_targets) and content_version>=6) then raise exception 'POLISH_VERSION_CHANGED';end if;
 for x in select d from polish_targets loop
  if md5(app_private.current_runtime_item_v1(x#>>'{source,id}')::text) is distinct from x#>>'{baseline,body_hash}' then raise exception 'POLISH_PREDECESSOR_CHANGED';end if;
  if not exists(select 1 from app_private.combat_content_records r where r.content_key=x#>>'{source,id}' and r.content_kind='item' and r.lifecycle='active' and r.revision=(x#>>'{baseline,revision}')::bigint and r.version_floor=(x#>>'{baseline,version_floor}')::integer and r.builtin_version=(x#>>'{baseline,builtin_version}')::integer) then raise exception 'POLISH_RECORD_CHANGED';end if;
 end loop;
 if (select count(*) from app_private.master_panel_role_assignments where role='game-owner' and enabled)<>1 then raise exception 'POLISH_OWNER_CHANGED';end if;
 select user_id into owner_id from app_private.master_panel_role_assignments where role='game-owner' and enabled;
 perform public.seed_runtime_item_sources_v1((select jsonb_agg(d->'source' order by d#>>'{source,id}') from polish_targets));
 for x in select d from polish_targets loop
  if not exists(select 1 from app_private.runtime_item_source_definitions s where s.item_id=x#>>'{source,id}' and s.content_version=6 and s.definition=x->'source') or not exists(select 1 from app_private.combat_content_records r where r.content_key=x#>>'{source,id}' and r.revision=(x#>>'{baseline,revision}')::bigint+1 and r.version_floor=6 and r.builtin_version=6) then raise exception 'POLISH_SOURCE_READBACK';end if;
 end loop;
 select d->'source' into ember from polish_targets where d#>>'{source,id}'='emberbrand';
 result:=public.commit_combat_content_record_v1(owner_id,null::uuid,'emberbrand',8,ember,public.read_combat_content_catalogue_token_v1(),6);
 if not exists(select 1 from app_private.combat_content_publications p join app_private.combat_content_versions v on v.id=p.version_id where p.content_key='emberbrand' and v.content_version=7 and v.definition=jsonb_set(ember,'{contentVersion}','7'::jsonb)) then raise exception 'POLISH_PUBLICATION_READBACK';end if;
end;$release$;
